  brush.fillTexture(0.9);
  brush.fillBleed(0.5);
  brush.vertex(400, 0);
  brush.vertex(200, 200);
  brush.vertex(0, 400);
  brush.endShape(true);

  brush.stroke(140, 180, 140, 60);
  brush.strokeWeight(3);

  brush.fillTexture(0.9, false);
  brush.stroke(70, 230, 255, 20);
  brush.strokeWeight(4);
  brush.circle(200, 200, 200);

  brush.fill(160, 80, 200, 60);
  brush.circle(200, 200, 140);
  brush.circle(200, 180, 80);
  brush.circle(200, 120, 80);

  brush.stroke(70, 70, 70, 80);
  brush.strokeWeight(5);
