```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#e08a72");
  let grassColor = "#98d971";
  let hills = 40;
  for (let hillIndex = 0; hillIndex < hills; hillIndex++) {
    if (hillIndex % 5 === 0) {
      grassColor = "#c4e292";
    } else {
      grassColor = "#b0c88d";
    }
    brush.fill(grassColor, 70);
    brush.circle(200 + hillIndex * 20, 170 + hillIndex * 10, 20 + hillIndex);
    brush.fill(grassColor, 70);
    brush.circle(200 + hillIndex * 20, 250 + hillIndex * 10, 20 + hillIndex);
  }
  brush.fill("#f77665", 50);
  brush.ellipse(200, 230, 200, 100);
  brush.fill("#b85c3a", 50);
  brush.ellipse(250, 220, 170, 100);
  brush.fill("#b8645b", 60);
  brush.ellipse(300, 210, 190, 100);
}
```

