function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.setFill((Date.now() + 20000) % 255);
  brush.strokeWidth(0);
  brush.setStroke(0.3);
  brush.strokeStyle(brush.parseColor("green"));
  brush.beginPath();
  brush.arc(200, 200, 100, 0, 360);
  brush.stroke();
  brush.strokeWidth(2);
  brush.strokeStyle(brush.parseColor("teal"));
  brush.beginPath();
  brush.arc(200, 150, 80, 0, 360);
  brush.stroke();
  brush.strokeWidth(0);
  brush.beginPath();
  brush.moveTo(180, 200);
  brush.lineTo(100, 150);
  brush.lineTo(400, 200);
  brush.stroke();
  brush.beginPath();
  brush.moveTo(200, 200);
  brush.lineTo(200, 300);
  brush.stroke();
  brush.beginShape(false);
  brush.vertex(100, 200);
  brush.vertex(200, 180);
  brush.vertex(200, 200);
  brush.vertex(200, 200);
  brush.vertex(400, 200);
  brush.endShape(true);
  brush.fillText(220, 200, 150);
  brush.drawText("fair enough", 300, 160);
}

