function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // sky
  brush.fill("#d8d8d8", 255);
  brush.fillBleed(0.7);
  brush.beginShape(1.5);
  brush.vertex(0, 0);
  brush.vertex(0, 400);
  brush.vertex(400, 400);
  brush.vertex(400, 0);
  brush.endShape();
  // hills
  brush.fill("#00ffcc", 150);
  brush.fillBleed(0.2);
  brush.fillTexture(1);
  brush.beginShape(1.5);
  brush.vertex(0, 100);
  brush.vertex(400, 100);
  brush.vertex(400, 250);
  brush.vertex(0, 250);
  brush.endShape();
  // ground
  brush.fill("#f5d6b0", 200);
  brush.fillBleed(0.75);
  brush.beginShape(2);
  brush.vertex(0, 300);
  brush.vertex(0, 400);
  brush.vertex(400, 300);
  brush.vertex(400, 400);
  brush.endShape();
  // details
  brush.fill("#fe6f51", 200);
  brush.fillBleed(0.8);
  brush.beginShape(1);
  brush.vertex(100, 200);
  brush.vertex(300, 200);
  brush.vertex(250, 150);
  brush.vertex(150, 150);
  brush.endShape();
  // hill textures
  brush.fill("#00ffcc", 100);
  brush.fillBleed(0.3);
  brush.fillTexture(1, 300);
  brush.beginShape(1);
  brush.vertex(0, 330);
  brush.vertex(0, 360);
  brush.vertex(100, 330);
  brush.vertex(100, 360);
  brush.endShape();
  // bracket
  brush.fill("#b47a56", 100);
  brush.fillBleed(0.7);
  brush.beginShape(1);
  brush.vertex(160, 150);
  brush.vertex(220, 120);
  brush.vertex(180, 120);
  brush.vertex(140, 120);
  brush.endShape();
}
