function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // sky
  stroke("#f3b682");
  strokeWeight(35);
  fill("#f3b682", 30);
  brush.circle(0, 400, 400);
  brush.vertex(0, 0);
  brush.vertex(200, 400);
  brush.vertex(400, 400);
  brush.vertex(200, 0);
  brush.endShape(true);

  stroke("#f4e682");
  strokeWeight(15);
  fill("#f4e682", 50);
  brush.circle(200, 100, 150);
  brush.vertex(0, 100);
  brush.vertex(200, 150);
  brush.vertex(400, 100);
  brush.vertex(200, 50);
  brush.endShape(true);

  stroke("#f3b682");
  strokeWeight(15);
  fill("#f3b682", 60);
  brush.circle(200, 150, 100);
  brush.vertex(0, 150);
  brush.vertex(200, 100);
  brush.vertex(400, 150);
  brush.vertex(200, 200);
  brush.endShape(true);

  stroke("#f3b682");
  strokeWeight(15);
  fill("#f3b682", 80);
  brush.circle(200, 200, 50);
  brush.vertex(0, 200);
  brush.vertex(200, 150);
  brush.vertex(400, 200);
  brush.vertex(200, 250);
  brush.endShape(true);

  stroke("#f08864");
  strokeWeight(20);
  fill("#f08864", 20);
  brush.circle(200, 250, 20);
